mapper.select:
SELECT id, sku_id, business_lot_key, source_lot_id, target_lot_id, planned_qty, issued_qty, received_qty, loss_confirmed_qty, active_receipt_quota, version
FROM transfer_line
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId} FOR UPDATE

SELECT id, sku_id, planned_qty, issued_qty, received_qty, loss_confirmed_qty, active_receipt_quota
FROM transfer_line
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}

SELECT id, warehouse_id, role, status
FROM transfer_leg
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}

SELECT transfer_id, line_id, warehouse_id, action, operation_id, quantity
FROM transfer_fact
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND action=#{action}
AND operation_id=#{operationId}

mapper.update:
UPDATE transfer_line
SET issued_qty=issued_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND issued_qty+#{qty}<=planned_qty

UPDATE transfer_line
SET received_qty=received_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND received_qty+loss_confirmed_qty+active_receipt_quota+#{qty}<=issued_qty

UPDATE transfer_order
SET status=#{status}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{transferId}

UPDATE transfer_leg
SET status=#{status}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND warehouse_id=#{warehouseId}

mapper.select:
SELECT id, transfer_id, transfer_line_id, target_warehouse_id, target_client_operation_id, quantity, state, token_version, target_result_ref
FROM receipt_authorization
WHERE enterprise_id=#{enterpriseId}
AND transfer_line_id=#{lineId}
AND target_client_operation_id=#{clientOperationId} FOR UPDATE

mapper.update:
UPDATE transfer_line
SET active_receipt_quota=active_receipt_quota+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND received_qty+loss_confirmed_qty+active_receipt_quota+#{qty}<=issued_qty

UPDATE transfer_line
SET received_qty=received_qty+#{qty}, active_receipt_quota=active_receipt_quota-#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND active_receipt_quota>=#{qty}

UPDATE transfer_line
SET active_receipt_quota=active_receipt_quota-#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND active_receipt_quota>=#{qty}

UPDATE transfer_line
SET loss_confirmed_qty=loss_confirmed_qty+#{qty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND received_qty+loss_confirmed_qty+active_receipt_quota+#{qty}<=issued_qty

UPDATE receipt_authorization
SET state=#{toState}, target_result_ref=#{resultRef}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}
AND state=#{fromState}
AND token_version=#{tokenVersion}

UPDATE transfer_line
SET target_lot_id=#{targetLotId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND transfer_id=#{transferId}
AND id=#{lineId}
AND (target_lot_id IS NULL OR target_lot_id=#{targetLotId})

mapper.select:
SELECT id, source_warehouse_id, target_warehouse_id, status, version, created_at
FROM transfer_order
WHERE enterprise_id=#{enterpriseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

SELECT id, source_warehouse_id, target_warehouse_id, status, version, created_at
FROM transfer_order
WHERE enterprise_id=#{enterpriseId}

    AND (source_warehouse_id IN #{warehouse}
        OR target_warehouse_id IN #{warehouse})
AND 1=0

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}
